/*
 * A021602  Decimal expansion of 1/598.
 * https://oeis.org/A021602
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   a(n) = the nth digit after the decimal point of 1/598
 *            (equivalently a(n) = floor(10^(n+1) / 598) % 10). The sequence
 *            is generated by a simple long‑division algorithm
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *digits = NULL;   /* cache of already computed digits */
    static size_t len   = 0;        /* number of digits stored                */
    static idx_t rem    = 1;        /* remainder after the last digit computed */

    size_t up = (size_t)n;          /* upper bound for the required digit */

    /* If the requested digit is already cached, return it. */
    if (n < (idx_t)len)
        return digits[up];

    /* Allocate or grow the cache if necessary. */
    if (digits == NULL) {
        digits = (seq_t *)malloc((up + 1) * sizeof(seq_t));
    } else if (len <= up) {
        digits = (seq_t *)realloc(digits, (up + 1) * sizeof(seq_t));
    }
    if (!digits)                     /* allocation failed */
        return (seq_t)0;

    /* Generate digits from the current end up to the requested position. */
    for (size_t i = len; i <= up; ++i) {
        seq_t d = (seq_t)((rem * 10) / 598);   /* the next decimal digit */
        rem   = (rem * 10) % 598;              /* update the remainder    */
        digits[i] = d;
    }
    len = up + 1;

    return digits[up];
}
